const leads = $input.first().json.leads || [];
const highPriority = leads.filter(l => (l.score?.totalScore || 0) >= 80);

let htmlReport = `<h2>David, here is your Daily AI Video Buyer Digest:</h2>`;
htmlReport += `<p>Found <b>${highPriority.length}</b> High-Priority Qualified Opportunities today.</p><ul>`;

highPriority.forEach(l => {
  htmlReport += `<li><b>${l.organization.name}</b> (${l.organization.country}) - Score: ${l.score.totalScore}/100<br/>` +
                `Signal: ${l.signal?.evidenceSummary}<br/>` +
                `Offer: <i>${l.recommendedService}</i></li><br/>`;
});
htmlReport += `</ul>`;

return [{ json: { htmlReport, count: highPriority.length } }];
